begin;
create function pg_temp.assert_true(p boolean,label text) returns void language plpgsql as $$ begin if p is distinct from true then raise exception 'FAILED: %',label; end if; end; $$;
grant execute on function pg_temp.assert_true(boolean,text) to authenticated,anon,service_role;
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-a000-000000000070','push-test@example.invalid',now()),('00000000-0000-4000-a000-000000000071','push-other@example.invalid',now());
insert into auth.sessions(id,user_id) values('00000000-0000-4000-b000-000000000070','00000000-0000-4000-a000-000000000070'),('00000000-0000-4000-b000-000000000071','00000000-0000-4000-a000-000000000071');
insert into private.account_consents(user_id,terms_version,privacy_version,age_16_confirmed) values('00000000-0000-4000-a000-000000000070','2026-10-17','2026-11-03',true),('00000000-0000-4000-a000-000000000071','2026-10-17','2026-11-03',true);
update private.nightlife_push_settings set enabled=true,token_hash=encode(extensions.digest(repeat('a',64),'sha256'),'hex'),attempts_today=0;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-a000-000000000070","role":"authenticated","session_id":"00000000-0000-4000-b000-000000000070"}',true);
set local role authenticated;
select pg_temp.assert_true((public.nightlife_notifications('preferences')->>'enabled')='false','default opt out');
do $$ begin begin perform public.nightlife_notifications('save','{"enabled":true,"venues":["evil"],"age_confirmed":true}'); raise exception 'Expected validation'; exception when sqlstate '22023' then null; end; end $$;
do $$ begin begin perform public.nightlife_notifications('save','{"enabled":true,"venues":["rarenightclub"],"age_confirmed":false}'); raise exception 'Expected age denial'; exception when raise_exception then if sqlerrm='Expected age denial' then raise; end if; end; end $$;
select public.nightlife_notifications('save','{"enabled":true,"venues":["rarenightclub"],"age_confirmed":true}');
select public.nightlife_notifications('register','{"token":"ExpoPushToken[syntheticTestToken70]","platform":"ios"}');
select pg_temp.assert_true((public.nightlife_notifications('register','{"token":"ExpoPushToken[syntheticTestToken70]","platform":"ios"}')->>'registered')='true','repeat registration is idempotent');
do $$ begin begin perform token from private.nightlife_push_devices; raise exception 'Expected denial'; exception when insufficient_privilege then null; end; end $$;
do $$ begin begin perform public.claim_nightlife_push(repeat('a',64)); raise exception 'Expected denial'; exception when insufficient_privilege then null; end; end $$;
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-a000-000000000071","role":"authenticated","session_id":"00000000-0000-4000-b000-000000000071"}',true);
set local role authenticated;
select pg_temp.assert_true((public.nightlife_notifications('preferences')->>'enabled')='false','other account cannot see preferences');
select public.nightlife_notifications('save','{"enabled":true,"venues":["rarenightclub"],"age_confirmed":true}');
do $$ begin begin perform public.nightlife_notifications('register','{"token":"ExpoPushToken[syntheticTestToken70]","platform":"ios"}'); raise exception 'Expected denial'; exception when insufficient_privilege then null; end; end $$;
reset role;
select set_config('request.jwt.claims','{}',true);
insert into public.instagram_feed_posts(id,source_username,post_url,caption,media_type,posted_at,moderation_status) values('push_test_old','rarenightclub','https://www.instagram.com/p/push_test_old/','Test','Image',now()-interval '2 days','approved'),('push_test_other','thepubonking','https://www.instagram.com/p/push_test_other/','Test','Image',now(),'approved'),('push_test_held','rarenightclub','https://www.instagram.com/p/testheld/','Test','Image',now(),'pending');
select pg_temp.assert_true((select count(*)=0 from private.nightlife_push_deliveries where token='ExpoPushToken[syntheticTestToken70]'),'no history, unselected venue or held post alerts');
insert into public.instagram_feed_posts(id,source_username,post_url,caption,media_type,posted_at,moderation_status) values('push_test_new','rarenightclub','https://www.instagram.com/p/push_test_new/','Test','Image',clock_timestamp(),'approved');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select private.review_post('push_test_new','approved');
update public.instagram_feed_posts set moderation_status='pending' where id='push_test_new';
select pg_temp.assert_true((select count(*)=1 from private.nightlife_push_deliveries where token='ExpoPushToken[syntheticTestToken70]'),'one alert per new selected post');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
do $$ begin begin perform public.claim_nightlife_push(repeat('b',64)); raise exception 'Expected denial'; exception when insufficient_privilege then null; end; end $$;
select pg_temp.assert_true((select count(*) from jsonb_array_elements(public.claim_nightlife_push(repeat('a',64))->'messages') item where item->>'token'='ExpoPushToken[syntheticTestToken70]')=1,'claim one alert');
select pg_temp.assert_true((select count(*) from jsonb_array_elements(public.claim_nightlife_push(repeat('a',64))->'messages') item where item->>'token'='ExpoPushToken[syntheticTestToken70]')=0,'no duplicate send after unknown outcome');
reset role;
select set_config('request.jwt.claims','{}',true);
insert into public.instagram_feed_posts(id,source_username,post_url,caption,media_type,posted_at,moderation_status) select 'push_test_cap_'||n,'rarenightclub','https://www.instagram.com/p/push_test_cap_'||n||'/','Test','Image',clock_timestamp(),'approved' from generate_series(1,10)n;
select private.review_post(id,'approved') from public.instagram_feed_posts where id like 'push_test_cap_%';
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select pg_temp.assert_true((select count(*) from jsonb_array_elements(public.claim_nightlife_push(repeat('a',64))->'messages') item where item->>'token'='ExpoPushToken[syntheticTestToken70]')=5,'six alerts maximum per device and day');
reset role;
update private.nightlife_push_settings set attempts_today=5000;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select pg_temp.assert_true((select count(*) from jsonb_array_elements(public.claim_nightlife_push(repeat('a',64))->'messages') item where item->>'token'='ExpoPushToken[syntheticTestToken70]')=0,'global daily cap');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-a000-000000000070","role":"authenticated","session_id":"00000000-0000-4000-b000-000000000070"}',true);
set local role authenticated;
select pg_temp.assert_true((public.account_privacy('export')->'notifications'->'devices'->0->>'platform')='ios','device metadata in export');
select pg_temp.assert_true(position('syntheticTestToken70' in public.account_privacy('export')::text)=0,'raw token excluded from data export');
select public.nightlife_notifications('save','{"enabled":false,"venues":["rarenightclub"],"age_confirmed":true}');
reset role;
select pg_temp.assert_true((select count(*)=0 from private.nightlife_push_devices where user_id='00000000-0000-4000-a000-000000000070'),'off removes devices');
select pg_temp.assert_true((select count(*)=0 from private.nightlife_push_deliveries where token='ExpoPushToken[syntheticTestToken70]'),'off cascades queue');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-a000-000000000070","role":"authenticated","session_id":"00000000-0000-4000-b000-000000000070"}',true);
set local role authenticated;
select public.nightlife_notifications('save','{"enabled":true,"venues":["rarenightclub"],"age_confirmed":true}');
select public.nightlife_notifications('register','{"token":"ExpoPushToken[syntheticTestToken70]","platform":"ios"}');
reset role;
delete from auth.sessions where id='00000000-0000-4000-b000-000000000070';
select pg_temp.assert_true((select count(*)=0 from private.nightlife_push_devices where user_id='00000000-0000-4000-a000-000000000070'),'revoked session removes device');
delete from auth.users where id='00000000-0000-4000-a000-000000000070';
select pg_temp.assert_true((select count(*)=0 from private.nightlife_notification_preferences where user_id='00000000-0000-4000-a000-000000000070'),'account deletion removes preferences');
rollback;
